'use strict';
const q=s=>document.querySelector(s);let map,regions=[],selected,pick='',start,end,marks=[],routeData,placeMarker;
function say(s){q('#message').textContent=s;}
function styleFor(r){return {version:8,glyphs:location.origin+'/map-data/assets/fonts/{fontstack}/{range}.pbf',sprite:location.origin+'/map-data/assets/sprites/v4/light',sources:{protomaps:{type:'vector',url:'pmtiles://'+location.origin+'/map-data/'+r.id+'.pmtiles',attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a> · <a href="https://protomaps.com">Protomaps</a>'}},layers:basemaps.layers('protomaps',basemaps.namedFlavor('light'),{lang:'en'})};}
function showInstructions(feature){
 const names={1:'Continue straight',2:'Turn left',3:'Bear left',4:'Sharp left',5:'Turn right',6:'Bear right',7:'Sharp right',8:'Keep left',9:'Keep right',10:'Make a U-turn',11:'Make a U-turn',12:'Off route',13:'Roundabout',14:'Roundabout',15:'Make a U-turn',16:'Continue off road',17:'Take the left exit',18:'Take the right exit',100:'Arrive'};
 const box=q('#route-summary');box.replaceChildren();
 for(const hint of feature.properties.voicehints||[]){const b=document.createElement('button');b.textContent=(names[hint[1]]||'Continue')+([13,14].includes(hint[1])?' - exit '+Math.abs(hint[2]):'')+'; then '+(hint[3]>=1000?(hint[3]/1000).toFixed(1)+' km':Math.round(hint[3])+' m');b.onclick=()=>map.flyTo({center:feature.geometry.coordinates[hint[0]].slice(0,2),zoom:16});box.append(b);}
 const end=document.createElement('p');end.textContent='Arrive at destination. Tap a step to see its location.';box.append(end);
}
function fit(){const b=selected.bounds;map.fitBounds([[b[0],b[1]],[b[2],b[3]]],{padding:30,maxZoom:12});}
function drawRoute(){if(!routeData||!map.isStyleLoaded())return;if(map.getSource('route'))map.getSource('route').setData(routeData);else{map.addSource('route',{type:'geojson',data:routeData});map.addLayer({id:'route',type:'line',source:'route',paint:{'line-color':'#d24158','line-width':5}});}}
async function boot(){try{
 const r=await fetch('/api/maps');if(!r.ok)throw Error('Map inventory unavailable.');const data=await r.json();regions=data.regions;
 q('#status').textContent=(data.download||'')+' · All map assets are stored on the SSD.';
 if(!regions.length){q('#map').textContent='Maps are downloading. Reopen this page when the first region is ready.';return;}
 for(const r of regions){const o=document.createElement('option');o.value=r.id;o.textContent=r.name+' · zoom '+r.maxzoom;q('#region').append(o);}
 selected=regions.find(r=>r.id==='singapore-malaysia')||regions[0];q('#region').value=selected.id;
 maplibregl.addProtocol('pmtiles',new pmtiles.Protocol().tile);
 map=new maplibregl.Map({container:'map',style:styleFor(selected),center:[103.82,1.35],zoom:11,maxZoom:19,attributionControl:true});map.addControl(new maplibregl.NavigationControl());map.addControl(new maplibregl.ScaleControl());
 map.on('style.load',drawRoute);map.on('error',e=>{q('#status').textContent='Some map data could not load. Check that this region has finished downloading.';console.warn(e.error);});
 q('#place-search').onsubmit=async e=>{e.preventDefault();const res=await fetch('/api/maps/search?q='+encodeURIComponent(q('#place-query').value)+'&lon='+map.getCenter().lng+'&lat='+map.getCenter().lat);const places=await res.json();const box=q('#places');box.replaceChildren();box.hidden=false;if(!places.length)box.textContent='No saved address or place found. Try the street name without the unit number; some addresses are not mapped.';for(const place of places){const b=document.createElement('button');b.textContent=place.name+' · '+(place.context||place.country)+(place.kind?' · '+place.kind:'');b.onclick=()=>{const preferred=regions.find(r=>r.id==='singapore-malaysia'&&place.lon>=98.8&&place.lon<=119.6&&place.lat>=.5&&place.lat<=7.8)||regions.find(r=>r.id==='southeast-asia'&&place.lon>=92&&place.lon<=142&&place.lat>=-11&&place.lat<=29)||regions.find(r=>r.id==='world');if(preferred&&preferred!==selected){selected=preferred;q('#region').value=selected.id;map.setStyle(styleFor(selected));}map.flyTo({center:[place.lon,place.lat],zoom:Math.min(selected.maxzoom,16)});if(placeMarker)placeMarker.remove();placeMarker=new maplibregl.Marker({color:'#173b58'}).setLngLat([place.lon,place.lat]).addTo(map);box.hidden=true;};box.append(b);}};
 q('#directions').addEventListener('toggle',()=>map.resize());
 q('#region').onchange=()=>{selected=regions.find(r=>r.id===q('#region').value);map.setStyle(styleFor(selected));fit();};q('#fit').onclick=fit;
 q('#full').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();map.resize();}catch{say('Use the Fieldstation maximise button above the map.');}};
 for(const key of ['start','end'])q('#'+key).onclick=()=>{pick=key;say('Tap the map to choose '+(key==='start'?'your start.':'your destination.'));};
 map.on('click',e=>{if(!pick)return;const point=[e.lngLat.lng,e.lngLat.lat];if(pick==='start')start=point;else end=point;pick='';marks.forEach(m=>m.remove());marks=[];for(const [p,color] of [[start,'#007e87'],[end,'#d24158']])if(p)marks.push(new maplibregl.Marker({color}).setLngLat(p).addTo(map));say(start&&end?'Ready to calculate route.':'Choose the other point.');});
 q('#clear').onclick=()=>{start=end=routeData=null;marks.forEach(m=>m.remove());marks=[];if(map.getLayer('route'))map.removeLayer('route');if(map.getSource('route'))map.removeSource('route');q('#route-summary').textContent='';say('Select two points to begin.');};
 q('#route').disabled=!data.routing;if(!data.routing)say('Routing data is still being prepared. Map browsing is available.');
 q('#route').onclick=async()=>{if(!start||!end){say('Choose both points first.');return;}q('#route').disabled=true;say('Calculating offline route…');try{const res=await fetch('/api/maps/route?'+new URLSearchParams({points:start.join(',')+'|'+end.join(','),profile:q('#mode').value}));const d=await res.json();if(!res.ok)throw Error(d.error);routeData=d;drawRoute();const p=d.features[0].properties;const dist=Number(p['track-length']);const time=Number(p['total-time']);say((dist/1000).toFixed(1)+' km'+(Number.isFinite(time)?' · about '+Math.round(time/60)+' min':''));showInstructions(d.features[0]);const coords=d.features[0].geometry.coordinates;const bounds=new maplibregl.LngLatBounds();coords.forEach(c=>bounds.extend(c.slice(0,2)));map.fitBounds(bounds,{padding:50});}catch(e){say(e.message);}finally{q('#route').disabled=false;}};
 }catch(e){q('#status').textContent=e.message;}}
boot();
